            T rv = 0;
            for (int i = 0; i < size; i++)
                rv |= static_cast<T>(p[i]) << (i * 8);
            return rv;
        }
        if (size == 1)
            return static_cast<T>(p[0]);
        return T(0);
    }
    else if constexpr (sizeof(T) == 4)
    {
        if (size == 4)
        {
            T rv;
            std::memcpy(&rv, p, 4);
            return rv;
        }
        if (size > 4)
        {
            T rv = 0;
            for (int i = 0; i < size; i++)
                rv |= static_cast<T>(p[i]) << (i * 8);
            return rv;
        }
        if (size == 2)
        {
            T rv = 0;
            std::memcpy(&rv, p, 2);
            return rv;
        }
        if (size == 1)
            return static_cast<T>(p[0]);
        return T(0);
    }
    else if constexpr (sizeof(T) == 8)
    {
        if (size == 8)
        {
            T rv;
            std::memcpy(&rv, p, 8);
            return rv;
        }
        if (size > 8)
        {
            T rv = 0;
            for (int i = 0; i < size; i++)
                rv |= static_cast<T>(p[i]) << (i * 8);
            return rv;
        }
        if (size == 4)
        {
            T rv = 0;
            std::memcpy(&rv, p, 4);
            return rv;
        }
        if (size == 2)
        {
            T rv = 0;
            std::memcpy(&rv, p, 2);
            return rv;
        }
        if (size == 1)
            return static_cast<T>(p[0]);
        return T(0);
    }
    else
    {
        if (size > sizeof(T))
        {
            T rv = 0;
            for (int i = 0; i < size; i++)
